"use strict";(globalThis.webpackChunkgrc||=[]).push([[14990],{35003(e){e.exports=JSON.parse('{"citeKey":"gurbani2003servicesspanning","slug":"gurbani-2003-services-spanning-75a3","title":"Services spanning heterogeneous networks","authors":["V. K. Gurbani","X.-H. Sun"],"venue":"The 2003 IEEE International Conference on Communications (ICC 2003), Anchorage, Alaska","type":"Conference","entryType":"inproceedings","date":"May, 2003","year":2003,"era":"iit","month":5,"doi":"10.1109/icc.2003.1204427","abstract":"Computer networks exist to provide services to users. In domains where more then one network dominates and provides useful services, users will want to avail themselves of services on either of the networks. This paper looks at the convergence of two networks in the telecommunication domain: the Internet and the Public Switched Telephone Network and discusses techniques to access services between the two networks, including an architecture for realizing services which would not be possible if either of the networks was operating in isolation.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2003/gurbani-2003-services-spanning-75a3.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);